1	// Page-level helpers for the draft-save regression tests.
2	//
3	// The core of every scenario is a race the product must survive: the user
4	// clicks save (or asks to reload the latest saved content), then keeps typing
5	// while the request is in flight. Real network round-trips are too fast to
6	// type against reliably, so before the page's own scripts run we install two
7	// independent gates on window.fetch:
8	//   - save gate: holds POST/PUT /api/articles calls until the test releases;
9	//   - read gate: holds GET /api/articles/:id calls (the single-article read
10	//     used by “编辑” and by the post-conflict “载入最新内容” button).
11	// The list fetch always passes through untouched. A one-shot failure arm can
12	// also make the next single-article read fail (404/500/network) without any
13	// test-only branch in the product.
14	//
15	// window.confirm is replaced by a controllable double (accept/cancel/native),
16	// because the reload flow asks the user to choose between keeping the current
17	// input and discarding it. The product itself has no test-only code paths.
18	const INIT_SOURCE = `(function () {
19	  if (window.__qtest) return;
20	  var origFetch = window.fetch.bind(window);
21	  var saveGate = { enabled: false, hits: 0, pending: [] };
22	  var readGate = { enabled: false, hits: 0, pending: [] };
23	  // null = off; 404/500 = respond with that status once; 'network' = reject once.
24	  var failNextRead = null;
25	
26	  function methodOf(init) { return ((init && init.method) || 'GET').toUpperCase(); }
27	  function pathOf(input) {
28	    var url = typeof input === 'string' ? input : ((input && input.url) || '');
29	    return url.split('?')[0];
30	  }
31	  function isSaveCall(path, method) {
32	    if (method !== 'POST' && method !== 'PUT') return false;
33	    return path === '/api/articles' || /^\\/api\\/articles\\/[^/]+$/.test(path);
34	  }
35	  function isItemRead(path, method) {
36	    return method === 'GET' && /^\\/api\\/articles\\/[^/]+$/.test(path);
37	  }
38	  function hold(gate, input, init) {
39	    gate.hits++;
40	    return new Promise(function (resolve) {
41	      gate.pending.push(function () { resolve(origFetch(input, init)); });
42	    });
43	  }
44	
45	  function failureResponse(mode) {
46	    var body = JSON.stringify({
47	      error: mode === 404 ? '模拟失败：该草稿已不存在' : '模拟失败：单篇读取暂时不可用'
48	    });
49	    return new Response(body, {
50	      status: mode,
51	      headers: { 'content-type': 'application/json' }
52	    });
53	  }
54	  // A single-article read may be parked by the read gate and/or fail once.
55	  // When both are armed the call parks; the failure is consumed at release so
56	  // the test can type during the wait before the error response arrives.
57	  function runItemRead(input, init) {
58	    if (failNextRead !== null) {
59	      var mode = failNextRead;
60	      failNextRead = null;
61	      if (mode === 'network') return Promise.reject(new Error('模拟的网络连接中断'));
62	      return Promise.resolve(failureResponse(mode));
63	    }
64	    return origFetch(input, init);
65	  }
66	
67	  window.fetch = function (input, init) {
68	    var path = pathOf(input);
69	    var method = methodOf(init);
70	    if (isItemRead(path, method)) {
71	      if (readGate.enabled) {
72	        readGate.hits++;
73	        return new Promise(function (resolve) {
74	          readGate.pending.push(function () { resolve(runItemRead(input, init)); });
75	        });
76	      }
77	      return runItemRead(input, init);
78	    }
79	    if (saveGate.enabled && isSaveCall(path, method)) return hold(saveGate, input, init);
80	    return origFetch(input, init);
81	  };
82	
83	  // Deterministic confirm double: 'accept' = 放弃当前输入, 'cancel' = 保留,
84	  // 'native' = fall through to the browser dialog (the harness auto-accepts
85	  // unexpected native dialogs and then fails the scenario).
86	  var nativeConfirm = typeof window.confirm === 'function' ? window.confirm.bind(window)
87	    : function () { return true; };
88	  var confirmBox = { mode: 'native', calls: [] };
89	  window.confirm = function (message) {
90	    confirmBox.calls.push(String(message));
91	    if (confirmBox.mode === 'accept') return true;
92	    if (confirmBox.mode === 'cancel') return false;
93	    return nativeConfirm(String(message));
94	  };
95	
96	  function byId(id) { return document.getElementById(id); }
97	  // Go through the prototype value setter so React-style change detection and
98	  // the page's input listeners see a genuine user edit.
99	  function setValue(id, value) {
100	    var node = byId(id);
101	    var proto = node.tagName === 'TEXTAREA'
102	      ? window.HTMLTextAreaElement.prototype
103	      : window.HTMLInputElement.prototype;
104	    Object.getOwnPropertyDescriptor(proto, 'value').set.call(node, value);
105	    node.dispatchEvent(new Event('input', { bubbles: true }));
106	    node.dispatchEvent(new Event('change', { bubbles: true }));
107	  }
108	  function releaseGate(gate) {
109	    var pending = gate.pending;
110	    gate.pending = [];
111	    pending.forEach(function (run) { run(); });
112	    return pending.length;
113	  }
114	  function gateView(gate) {
115	    return { enabled: gate.enabled, hits: gate.hits, pending: gate.pending.length };
116	  }
117	  window.__qtest = {
118	    set: function (id, value) { setValue(id, value); },
119	    click: function (id) { byId(id).click(); },
120	    clickEdit: function (title) {
121	      var cards = document.querySelectorAll('#article-list article.draft');
122	      for (var i = 0; i < cards.length; i++) {
123	        var h3 = cards[i].querySelector('h3');
124	        var text = h3 && h3.firstChild ? h3.firstChild.nodeValue : '';
125	        if (text === title) { cards[i].querySelector('button').click(); return true; }
126	      }
127	      return false;
128	    },
129	    clickConflictAction: function (label) {
130	      var btns = document.querySelectorAll('#conflict-box .actions button');
131	      for (var i = 0; i < btns.length; i++) {
132	        if (btns[i].textContent === label) { btns[i].click(); return true; }
133	      }
134	      return false;
135	    },
136	    gateOn: function () { saveGate.enabled = true; saveGate.hits = 0; },
137	    gateOff: function () { saveGate.enabled = false; },
138	    release: function () { return releaseGate(saveGate); },
139	    gateState: function () { return gateView(saveGate); },
140	    readGateOn: function () { readGate.enabled = true; readGate.hits = 0; },
141	    readGateOff: function () { readGate.enabled = false; },
142	    releaseReads: function () { return releaseGate(readGate); },
143	    readGateState: function () { return gateView(readGate); },
144	    armReadFailure: function (mode) { failNextRead = mode; },
145	    readFailureArmed: function () { return failNextRead; },
146	    confirmMode: function (mode) { confirmBox.mode = mode; },
147	    confirmReset: function () { confirmBox.calls = []; },
148	    confirmState: function () {
149	      return { mode: confirmBox.mode, calls: confirmBox.calls.slice() };
150	    }
151	  };
152	  window.__snap = function () {
153	    function v(id) { return document.getElementById(id).value; }
154	    var status = document.getElementById('status');
155	    var banner = document.getElementById('edit-banner');
156	    var cards = Array.prototype.map.call(
157	      document.querySelectorAll('#article-list article.draft'),
158	      function (card) {
159	        var h3 = card.querySelector('h3');
160	        var sum = card.querySelector('.summary');
161	        var btn = card.querySelector('.actions button');
162	        return {
163	          title: h3 && h3.firstChild ? h3.firstChild.nodeValue : '',
164	          summary: sum ? sum.textContent : null,
165	          editing: !!card.querySelector('.editing-tag'),
166	          editBtnText: btn ? btn.textContent : '',
167	          editBtnDisabled: btn ? btn.disabled : null
168	        };
169	      });
170	    var code = banner.querySelector('code');
171	    var meta = banner.querySelector('.meta');
172	    return {
173	      form: { title: v('title'), summary: v('summary'), body: v('body') },
174	      fieldsEditable: {
175	        title: !byId('title').disabled,
176	        summary: !byId('summary').disabled,
177	        body: !byId('body').disabled
178	      },
179	      saveBtnText: document.getElementById('save-btn').textContent,
180	      saveDisabled: document.getElementById('save-btn').disabled,
181	      cancelHidden: document.getElementById('cancel-btn').hidden,
182	      formEditing: document.getElementById('draft-form').classList.contains('editing'),
183	      bannerHidden: banner.hidden,
184	      bannerTitle: code ? code.textContent : null,
185	      bannerId: meta ? (meta.textContent.split('标识：')[1] || '') : '',
186	      statusText: status.textContent,
187	      statusKind: (status.className.match(/\\b(ok|err|warn)\\b/) || [])[1] || '',
188	      conflictHidden: document.getElementById('conflict-box').hidden,
189	      cards: cards,
190	      listCount: cards.length,
191	      emptyTip: document.getElementById('empty-tip').textContent
192	    };
193	  };
194	})();`;
195	
196	export async function open(browser, baseUrl) {
197	  const page = await browser.newPage();
198	  await page.enable();
199	  await page.addInitScript(INIT_SOURCE);
200	  await page.goto(baseUrl);
201	  // Initial list fetch has settled.
202	  await page.waitFor(
203	    'function(){return !document.getElementById("empty-tip").textContent.includes("加载中");}',
204	    { label: 'initial draft list settled' });
205	  return page;
206	}
207	
208	export async function reload(page) {
209	  await page.reload();
210	  await page.waitFor(
211	    'function(){return !document.getElementById("empty-tip").textContent.includes("加载中");}',
212	    { label: 'draft list settled after reload' });
213	}
214	
215	export async function fill(page, fields) {
216	  for (const [id, value] of Object.entries(fields)) {
217	    await page.eval(`__qtest.set(${JSON.stringify(id)}, ${JSON.stringify(value)})`);
218	  }
219	}
220	
221	export async function clickSave(page) {
222	  await page.eval(`__qtest.click('save-btn')`);
223	}
224	
225	export async function clickCancel(page) {
226	  await page.eval(`__qtest.click('cancel-btn')`);
227	}
228	
229	export async function clickEdit(page, title) {
230	  const clicked = await page.eval(`__qtest.clickEdit(${JSON.stringify(title)})`);
231	  if (!clicked) throw new Error(`no draft card titled ${JSON.stringify(title)} to edit`);
232	}
233	
234	// Buttons inside the conflict comparison box.
235	export async function clickConflictAction(page, label) {
236	  const clicked = await page.eval(`__qtest.clickConflictAction(${JSON.stringify(label)})`);
237	  if (!clicked) throw new Error(`no conflict action button ${JSON.stringify(label)}`);
238	}
239	
240	export const DISCARD_AND_LOAD = '放弃当前输入并载入最新内容';
241	export const KEEP_MINE = '保留我的输入，继续修改';
242	export async function clickDiscardLoad(page) {
243	  await clickConflictAction(page, DISCARD_AND_LOAD);
244	}
245	
246	export async function gateOn(page) { await page.eval(`__qtest.gateOn()`); }
247	export async function gateOff(page) { await page.eval(`__qtest.gateOff()`); }
248	export async function releaseSaves(page) { return page.eval(`__qtest.release()`); }
249	export function gateState(page) { return page.eval(`__qtest.gateState()`); }
250	
251	// Single-article read gate (GET /api/articles/:id).
252	export async function readGateOn(page) { await page.eval(`__qtest.readGateOn()`); }
253	export async function readGateOff(page) { await page.eval(`__qtest.readGateOff()`); }
254	export async function releaseReads(page) { return page.eval(`__qtest.releaseReads()`); }
255	export function readGateState(page) { return page.eval(`__qtest.readGateState()`); }
256	
257	// Make the next single-article GET fail once: 404, 500 or 'network'.
258	export async function armReadFailure(page, mode) {
259	  await page.eval(`__qtest.armReadFailure(${JSON.stringify(mode)})`);
260	}
261	export function readFailureArmed(page) {
262	  return page.eval(`__qtest.readFailureArmed()`);
263	}
264	
265	// Control the page's window.confirm double.
266	export async function setConfirm(page, mode) {
267	  await page.eval(`__qtest.confirmMode(${JSON.stringify(mode)})`);
268	}
269	export async function resetConfirm(page) {
270	  await page.eval(`__qtest.confirmReset()`);
271	}
272	export function confirmState(page) {
273	  return page.eval(`__qtest.confirmState()`);
274	}
275	
276	// The save request is parked in the browser and the UI shows its in-flight state.
277	export async function waitSavingPending(page, count = 1) {
278	  await page.waitFor(
279	    `function(){var g=__qtest.gateState();return g.pending===${count} && __snap().saveDisabled && __snap().saveBtnText==='保存中…';}`,
280	    { timeout: 5000, label: `save request #${count} parked while button shows 保存中…` });
281	}
282	
283	// The single-article read triggered by the conflict “载入最新内容” button is
284	// parked; the page shows the reading state without clearing the form.
285	export async function waitReadPending(page, count = 1) {
286	  await page.waitFor(
287	    `function(){var g=__qtest.readGateState();return g.pending===${count} && __snap().saveDisabled && __snap().saveBtnText==='读取中…';}`,
288	    { timeout: 5000, label: `article read #${count} parked while button shows 读取中…` });
289	}
290	
291	export function state(page) {
292	  return page.eval(`__snap()`);
293	}
294	
295	export async function waitForStatus(page, text, kind) {
296	  const kindCheck = kind ? ` && s.statusKind===${JSON.stringify(kind)}` : '';
297	  await page.waitFor(
298	    `function(){var s=__snap();return s.statusText.includes(${JSON.stringify(text)})${kindCheck};}`,
299	    { timeout: 8000, label: `status containing ${JSON.stringify(text)}${kind ? ` (${kind})` : ''}` });
300	}
301	
302	export async function waitLoadedDraft(page) {
303	  await waitForStatus(page, '已载入该草稿当前保存的内容');
304	  await page.waitFor('function(){return !__snap().bannerHidden && __snap().saveBtnText==="保存修改";}',
305	    { label: 'editing banner and 保存修改 button' });
306	}
307	
308	// The 409 comparison box is visible with its two action buttons.
309	export async function waitConflictShown(page) {
310	  await page.waitFor(
311	    `function(){return !__snap().conflictHidden
312	      && document.querySelectorAll('#conflict-box .ver.mine dd').length===3
313	      && document.querySelectorAll('#conflict-box .ver.saved dd').length===3
314	      && document.querySelectorAll('#conflict-box .actions button').length===2;}`,
315	    { timeout: 5000, label: 'conflict comparison box with both action buttons' });
316	}
317	
318	export async function getConflict(page) {
319	  return page.eval(`(function () {
320	    var box = document.getElementById('conflict-box');
321	    function column(selector) {
322	      var ver = box.querySelector(selector);
323	      if (!ver) return null;
324	      var dds = ver.querySelectorAll('dd');
325	      function val(dd) { return dd.classList.contains('empty-field') ? '' : dd.textContent; }
326	      return {
327	        heading: ver.querySelector('h4').textContent,
328	        title: val(dds[0]),
329	        summary: val(dds[1]),
330	        body: val(dds[2])
331	      };
332	    }
333	    return {
334	      hidden: box.hidden,
335	      heading: box.querySelector('h3') ? box.querySelector('h3').textContent : '',
336	      mine: column('.ver.mine'),
337	      saved: column('.ver.saved'),
338	      actions: Array.prototype.map.call(
339	        box.querySelectorAll('.actions button'),
340	        function (btn) { return { text: btn.textContent, disabled: btn.disabled }; })
341	    };
342	  })()`);
343	}
344	
345	export function assertNoPageErrors(page) {
346	  if (page.pageErrors.length) {
347	    throw new Error(`uncaught page errors:\n${page.pageErrors.join('\n')}`);
348	  }
349	  const errors = page.consoleMessages.filter((m) => m.type === 'error');
350	  if (errors.length) {
351	    throw new Error(`console errors:\n${errors.map((m) => m.text).join('\n')}`);
352	  }
353	  if (page.dialogs.length) {
354	    throw new Error(`unexpected native confirm/alert dialogs (dirty-guard fired?):\n${page.dialogs.join('\n---\n')}`);
355	  }
356	}
