    assert.match(s.emptyTip, /网络连接中断/);
    assert.ok(!s.emptyTip.includes('还没有保存的草稿'));
    assert.deepEqual(await server.listArticles(), []);
  } finally {
    await closeContext({ server, page }, browser);
  }
});

